insert into public.products
(product_code, name, short_description, detailed_description, category, usage_tags, color_tags, pattern_tags, material, production_method, origin, manufacturer, width_mm, height_mm, thickness, weight_gsm, strength_level, transparency_level, texture, inkjet_compatible, laser_printer_compatible, calligraphy_compatible, food_contact_compatible, water_resistant, heat_resistant, indoor_compatible, outdoor_compatible, price, tax_included_price, stock_quantity, low_stock_threshold, minimum_order_quantity, image_urls, purchase_url, caution_notes, recommended_uses, prohibited_uses, is_published)
values
('WA-001', '越前手すき和紙「淡桜」', '落ち着いた淡い桜色の手すき和紙。金銀の繊維が控えめに入った上品な一枚。', '福井県越前市の工房で一枚ずつ漉かれた楮(こうぞ)100%の手すき和紙です。淡い桜色に金銀の繊維が控えめに散らされており、華やかさがありながら派手すぎません。結婚祝いなど慶事の包装に人気です。', '包装用和紙', '{包装,ギフト}', '{淡い色,赤系,落ち着いた色}', '{金銀入り,手すき模様}', '楮', '手すき', '福井県越前市', '淡雪紙工房(架空)', 640, 940, '中厚', 45, 3, 2, 'しっとりとした柔らかな風合い', false, false, false, false, false, false, true, false, 500, 550, 12, 5, 1, '{}', 'https://example.com/shop/WA-001', '手すき和紙のため色合いや柄に若干の個体差があります。水濡れに弱いため水回りでは使用しないでください。', '{結婚祝いの包装,慶事のギフト包装,御祝の包み紙}', '{食品の直接包装,屋外使用}', true),

('WA-002', '美濃機械すき和紙「白雪」', '純白でなめらかな機械すき和紙。包装の定番でお手頃価格。', '岐阜県美濃市で漉かれた機械すき和紙です。純白でなめらかな表面が特長で、包装や工作の下地など幅広く使えます。大量に必要な場合にも対応しやすい定番商品です。', '包装用和紙', '{包装,工作}', '{白}', '{無地}', 'パルプ・楮混合', '機械すき', '岐阜県美濃市', '美濃白川製紙(架空)', 636, 939, '薄口', 35, 2, 3, 'なめらかで均一', false, false, false, false, false, false, true, false, 220, 242, 80, 10, 1, '{}', 'https://example.com/shop/WA-002', '薄手のため強く引っ張ると破れることがあります。', '{ギフト包装,箱の包装,工作の下地}', '{食品の直接包装}', true),

('WA-003', '友禅和紙「花明かり」', '華やかな花柄の友禅和紙。贈り物や海外土産に人気。', '京都で染められた友禅和紙です。赤を基調に四季の花々が描かれ、開いた瞬間に華やぐ一枚です。小箱の包装や工作、海外への贈り物に人気があります。', '包装用和紙', '{包装,ギフト,工作,海外土産}', '{赤系,鮮やかな色}', '{花柄,和柄}', '楮', '機械すき・シルクスクリーン印刷', '京都府', '京友禅紙店(架空)', 480, 660, '中厚', 48, 3, 2, 'しっかりとした手触り', false, false, false, false, false, false, true, false, 380, 418, 35, 5, 1, '{}', 'https://example.com/shop/WA-003', '柄の出方が1枚ごとに異なります。', '{ギフト包装,海外への贈り物,和小物づくり}', '{食品の直接包装}', true),

('WA-004', '無地和紙「藍空」', '落ち着いた藍色の無地和紙。上品な贈答用に。', '高知県の伝統的な技法で漉かれた藍色の無地和紙です。深く落ち着いた色合いで、目上の方への贈り物やシックな包装に適しています。', '包装用和紙', '{包装,ギフト,インテリア}', '{青系,落ち着いた色}', '{無地}', '楮・パルプ', '機械すき', '高知県', '土佐紙匠(架空)', 640, 940, '中厚', 44, 3, 2, 'やわらかな風合い', false, false, false, false, false, false, true, false, 320, 352, 40, 5, 1, '{}', 'https://example.com/shop/WA-004', '濃色のため摩擦で色移りする場合があります。', '{落ち着いた贈答用の包装,インテリア}', '{食品の直接包装,水回り}', true),

('WA-005', '障子紙「里の月」', '標準的な白の障子紙。柔らかな光が入る定番品。', '一般家庭向けの標準的な障子紙です。光をよく通し、部屋を明るく柔らかな雰囲気にします。障子1枚分(幅94cm)をカバーできるサイズです。', '障子紙', '{障子}', '{白}', '{無地}', 'パルプ・レーヨン', '機械すき', '岐阜県', '美濃白川製紙(架空)', 940, 2150, '薄口', 28, 3, 4, 'ややざらつきのある自然な質感', false, false, false, false, false, false, true, false, 780, 858, 25, 5, 1, '{}', 'https://example.com/shop/WA-005', '貼り替え時はでんぷんのりをご使用ください。標準タイプのため、ペットや小さなお子様のいるご家庭には強化タイプをおすすめします。', '{障子の張り替え}', '{屋外使用,水回り}', true),

('WA-006', '強化障子紙「守り布」', '破れにくい強化障子紙。通常の約4倍の強度。', '樹脂で強化した破れにくい障子紙です。通常の障子紙の約4倍の強度があり、ペットや小さなお子様のいるご家庭に選ばれています。', '障子紙', '{障子}', '{白}', '{無地}', 'パルプ・樹脂強化', '機械すき', '岐阜県', '美濃白川製紙(架空)', 940, 2150, '中厚', 38, 5, 3, 'つるりとした均一な質感', false, false, false, false, true, false, true, false, 1280, 1408, 18, 5, 1, '{}', 'https://example.com/shop/WA-006', '専用のりまたは両面テープで貼り付けてください。一般のでんぷんのりでは接着が弱い場合があります。', '{障子の張り替え,ペットのいる家庭の障子}', '{}', true),

('WA-007', 'インクジェット和紙 A4「墨遊び」20枚入', '家庭用インクジェットプリンター対応のA4和紙。', '家庭用インクジェットプリンターで印刷できるA4サイズの和紙です。印刷面は発色よく仕上がり、裏面は和紙本来の風合いを楽しめます。招待状やメッセージカード、名刺づくりに人気です。', '印刷用和紙', '{印刷,招待状,名刺,工作}', '{白,生成り}', '{無地}', '楮・パルプ', '機械すき', '愛媛県', '伊予紙工(架空)', 210, 297, '中厚', 80, 3, 2, '印刷面はなめらか・裏面は和紙の風合い', true, false, false, false, false, false, true, false, 980, 1078, 50, 10, 1, '{}', 'https://example.com/shop/WA-007', 'インクジェットプリンター専用です。レーザープリンター・コピー機では使用できません(故障の原因になります)。給紙は1枚ずつ行うと紙詰まりを防げます。印刷後はインクを十分に乾かしてください。', '{招待状の印刷,名刺づくり,メッセージカードの印刷}', '{レーザープリンターでの印刷,食品包装}', true),

('WA-008', 'レーザー対応和紙 A4「白練」30枚入', 'レーザープリンター・コピー機対応の和紙風用紙。', 'レーザープリンターやコピー機で使える耐熱加工済みのA4和紙風用紙です。ハリがあり、名刺や会社案内など上質感を出したい印刷物に適しています。', '印刷用和紙', '{印刷,名刺,招待状}', '{白}', '{無地}', 'パルプ・楮混合', '機械すき', '静岡県', '駿河紙業(架空)', 210, 297, '中厚', 90, 4, 1, 'ハリのあるなめらかな質感', false, true, false, false, false, true, true, false, 1480, 1628, 30, 10, 1, '{}', 'https://example.com/shop/WA-008', 'レーザープリンター・コピー機対応です。インクジェットでは滲む場合があります。', '{名刺の印刷,招待状,会社案内}', '{食品包装}', true),

('WA-009', '書道半紙「白鶴」100枚入', '練習に最適な書道半紙。にじみが穏やかで書きやすい。', '書道の練習に適した半紙です。にじみが穏やかで筆運びがなめらか。学校や書道教室でも使いやすい定番品です。', '書道用和紙', '{書道}', '{白}', '{無地}', 'パルプ・竹', '機械すき', '山梨県', '甲斐製紙(架空)', 243, 334, '薄口', 24, 2, 3, '墨のにじみが穏やか', false, false, true, false, false, false, true, false, 850, 935, 60, 10, 1, '{}', 'https://example.com/shop/WA-009', '練習用に適した半紙です。展覧会などの作品用には画仙紙をご検討ください。', '{書道の練習,学校の書写}', '{}', true),

('WA-010', '画仙紙「山水」10枚入', '書道作品・水墨画向けの大判画仙紙。', '書道作品や水墨画に適した大判の画仙紙です。墨の濃淡やかすれが美しく表現でき、作品制作に向いています。', '書道用和紙', '{書道,絵画}', '{白}', '{無地}', '楮・稲わら', '手すき', '山口県', '長門紙房(架空)', 700, 1360, '中厚', 32, 2, 3, '墨のにじみとかすれが美しい', false, false, true, false, false, false, true, false, 1600, 1760, 22, 5, 1, '{}', 'https://example.com/shop/WA-010', '湿気に弱いため乾燥した場所で保管してください。', '{書道作品,水墨画}', '{プリンター印刷}', true),

('WA-011', '絵画用厚口和紙「大地」', '岩絵具や水彩に耐える厚口の手すき和紙。', '日本画や水彩画に適した厚口の手すき和紙です。表面に凹凸があり、岩絵具や水彩絵具をしっかり受け止めます。額装しても存在感のある一枚です。', '絵画用和紙', '{絵画,工作,インテリア}', '{生成り}', '{無地,手すき模様}', '楮', '手すき', '富山県', '越中紙舎(架空)', 560, 760, '厚口', 110, 5, 1, '表面に凹凸のある力強い質感', false, false, true, false, false, false, true, false, 480, 528, 28, 5, 1, '{}', 'https://example.com/shop/WA-011', '厚手のため折り曲げる用途には適しません。', '{日本画,水彩画,額装アート}', '{障子,プリンター印刷}', true),

('WA-012', '工作用和紙 いろどり15色セット', '鮮やかな15色入り。子供の工作やちぎり絵に。', '鮮やかな15色をセットにした工作用の和紙です。手でちぎりやすく、ちぎり絵や折り紙、貼り絵など幅広い工作に使えます。', '工作用和紙', '{工作,ギフト}', '{鮮やかな色,赤系,青系,緑系,黄色系}', '{無地}', 'パルプ', '機械すき', '愛媛県', '伊予紙工(架空)', 250, 250, '薄口', 30, 2, 2, 'やわらかく折りやすい', false, false, false, false, false, false, true, false, 650, 715, 45, 10, 1, '{}', 'https://example.com/shop/WA-012', '色によって若干厚みが異なります。', '{折り紙,ちぎり絵,子供の工作}', '{食品包装}', true),

('WA-013', 'もみ紙「茜」', 'もみ加工の陰影が美しい赤系の和紙。', 'もみ加工によるしわの陰影が美しい、深い茜色の和紙です。壁面装飾やディスプレイ、包装のアクセントに使うと空間が引き締まります。', 'インテリア和紙', '{インテリア,工作,包装,店舗装飾}', '{赤系,落ち着いた色}', '{手すき模様}', '楮', '手すき・もみ加工', '埼玉県小川町', '武蔵野和紙店(架空)', 530, 780, '中厚', 50, 3, 2, 'しわの陰影が美しい', false, false, false, false, false, false, true, false, 420, 462, 15, 5, 1, '{}', 'https://example.com/shop/WA-013', 'もみ加工のため、しわの入り方に個体差があります。', '{壁面装飾,店舗ディスプレイ,包装のアクセント}', '{プリンター印刷,水回り}', true),

('WA-014', '雲龍紙「白雲 生成り」', '繊維の流れが美しい雲龍紙。光を柔らかく通す。', '長い繊維が雲のように流れる雲龍紙です。光を柔らかく通すため、LED照明のシェードや間仕切り、ディスプレイに適しています。', 'インテリア和紙', '{インテリア,照明,店舗装飾,工作}', '{生成り,淡い色}', '{手すき模様}', '楮', '機械すき', '高知県', '土佐紙匠(架空)', 640, 940, '薄口', 30, 3, 4, '繊維の表情が豊か', false, false, false, false, false, false, true, false, 380, 418, 33, 5, 1, '{}', 'https://example.com/shop/WA-014', '照明に使用する場合は発熱の少ないLED光源をご使用ください。白熱電球は高温になるため使用できません。', '{LEDランプシェード,間仕切り,ディスプレイ}', '{白熱電球の照明,屋外使用}', true),

('WA-015', '照明用難燃和紙「灯り雲」', '難燃加工済みの照明向け和紙。店舗照明にも。', '難燃加工を施した照明向けの和紙です。柔らかな光を通し、住宅の照明カバーから店舗照明まで幅広く使えます。', '照明用和紙', '{照明,インテリア,店舗装飾}', '{白,生成り}', '{手すき模様}', '楮・難燃加工', '機械すき', '福井県', '淡雪紙工房(架空)', 640, 940, '中厚', 42, 4, 4, '柔らかな光を通す', false, false, false, false, false, true, true, false, 880, 968, 10, 5, 1, '{}', 'https://example.com/shop/WA-015', '難燃加工済みですが、光源はLEDを推奨します。照明器具の定格・取扱説明書を必ず確認してください。', '{ランプシェード,照明カバー,店舗照明}', '{屋外照明,水回り}', true),

('WA-016', '照明用和紙「月光」', '薄く光をよく通すLED専用の照明向け和紙。', '雁皮を配合した薄手の和紙で、透け感が美しく、LED照明のシェードに適しています。上品な光の演出ができます。', '照明用和紙', '{照明,インテリア}', '{白}', '{無地}', '雁皮・パルプ', '機械すき', '兵庫県', '播磨紙匠(架空)', 585, 900, '薄口', 25, 2, 5, '透け感が美しい', false, false, false, false, false, false, true, false, 680, 748, 8, 10, 1, '{}', 'https://example.com/shop/WA-016', 'LED光源専用です。白熱電球・ハロゲンランプなど高温になる光源には絶対に使用しないでください。', '{LEDランプシェード}', '{白熱電球・ハロゲン光源,屋外使用}', true),

('WA-017', '和紙ギフトセット「折々」', '人気の和紙5種を詰め合わせ。海外土産の定番。', '当店人気の和紙5種類を桐箱風の化粧箱に詰め合わせたギフトセットです。約180gと軽量で、スーツケースにも入れやすく、海外へのお土産に選ばれています。', 'ギフト商品', '{ギフト,海外土産}', '{淡い色,鮮やかな色}', '{花柄,和柄,無地}', '楮ほか', '手すき・機械すき', '日本各地', '淡雪紙工房(架空)', 300, 420, '中厚', null, 3, 2, '5種それぞれ異なる風合い', false, false, false, false, false, false, true, false, 2800, 3080, 20, 5, 1, '{}', 'https://example.com/shop/WA-017', 'セット内容は時期により一部変わることがあります。', '{海外へのお土産,和紙好きへの贈り物}', '{}', true),

('WA-018', '和紙ブックカバー 文庫判', '撥水加工のもみ和紙ブックカバー。丈夫で長持ち。', 'もみ加工と撥水加工を施した丈夫な和紙のブックカバーです。使うほどに手になじみ、革のような風合いに育ちます。文庫本サイズ対応。', '和紙小物', '{ギフト,海外土産}', '{青系,落ち着いた色}', '{和柄}', '楮・撥水加工', '手すき・もみ加工', '埼玉県小川町', '武蔵野和紙店(架空)', 160, 300, '厚口', null, 4, 1, 'しなやかで丈夫', false, false, false, false, true, false, true, false, 2400, 2640, 25, 5, 1, '{}', 'https://example.com/shop/WA-018', '撥水加工済みですが完全防水ではありません。', '{読書好きへの贈り物,海外へのお土産}', '{}', true),

('WA-019', '和紙のし袋・金封 3枚組', '手すき和紙の祝儀袋。結婚祝いなど慶事に。', '手すき和紙で仕立てた上品な祝儀袋の3枚組です。金銀の水引付きで、結婚祝いやお祝い事にそのまま使えます。中袋付き。', '和紙小物', '{ギフト}', '{白,金・銀}', '{金銀入り,和柄}', '楮', '手すき', '福井県', '淡雪紙工房(架空)', 105, 185, '中厚', null, 3, 1, '上品な手すきの質感', false, false, false, false, false, false, true, false, 600, 660, 70, 10, 1, '{}', 'https://example.com/shop/WA-019', '中袋付きです。表書きは筆ペンでの記入がおすすめです。', '{結婚祝い,御祝,慶事の金封}', '{}', true),

('WA-020', '金銀水引 10本セット', 'あわじ結びに使いやすい金銀の水引。', '長さ約90cmの金銀水引10本セットです。祝儀袋の飾りやラッピングのアクセント、水引細工に使えます。', '水引', '{ギフト,加工用品}', '{金・銀}', '{無地}', '紙・金属糸', null, '長野県飯田市', '飯田水引堂(架空)', null, 900, null, null, null, null, 'ハリのある質感', false, false, false, false, false, false, true, false, 450, 495, 90, 15, 1, '{}', 'https://example.com/shop/WA-020', '長さ約90cm。はさみで簡単にカットできます。', '{祝儀袋の飾り,ラッピングのアクセント,水引細工}', '{}', true),

('WA-021', '和紙メッセージカード 10枚(封筒付)', 'インクジェット対応の和紙カード。封筒付き。', '厚手の和紙で作ったメッセージカード10枚セットです。封筒付きで、手書きにもインクジェット印刷にも対応。贈り物に添えるカードとして人気です。', 'メッセージカード', '{ギフト,印刷,メッセージカード}', '{白,生成り}', '{無地,手すき模様}', '楮・パルプ', '機械すき', '愛媛県', '伊予紙工(架空)', 100, 148, '厚口', 180, 4, 1, 'しっかりした厚み', true, false, false, false, false, false, true, false, 980, 1078, 55, 10, 1, '{}', 'https://example.com/shop/WA-021', 'インクジェット対応(レーザープリンター不可)。手書きの場合はボールペン・筆ペンが適しています。', '{贈り物に添えるカード,招待状,お礼状}', '{レーザープリンターでの印刷}', true),

